        pattern = r'\b\d{4}-\d{2}-\d{4}\b'
        return re.findall(pattern, text)

    def extract_license_numbers(text):
        pattern = r'\b\d{2}-\d{2}-\d{4}\b'
        return re.findall(pattern, text)

    def extract_vehicle_ids(text):
        pattern = r'\b\d{1,3}[A-Z]{2}-\d{4}\b'
        return re.findall(pattern, text)

    def extract_device_ids(text):
        pattern = r'\b\d{1,3}[A-Z]{2}-\d{4}\b'
        return re.findall(pattern, text)

